import { useTranslation } from 'react-i18next';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import { Box, Center, Stack, Grid, GridItem } from 'styled-system/jsx';
import { Card } from '~/components/ui/card';
import { Heading } from '~/components/ui/heading';
import { Spinner } from '~/components/ui/spinner';
import { Text } from '~/components/ui/text';
import { useBluebirdSummary } from '~/hooks/useBluebirdSummary';
import MainContentAndRightSidebar from '~/components/layout/MainContentAndRightSidebar';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

export default function Page() {
  const { t } = useTranslation();
  const { data, isLoading, isError, error } = useBluebirdSummary();

  const chartData = data
    ? {
        labels: Array.from({ length: 24 }, (_, i) => i),
        datasets: data.postsPerMember.map((author) => ({
          label: author.name,
          data: Array.from({ length: 24 }, (_, i) => {
            const hourData = data.postsByHourAndMember.find(
              (entry) => entry.hour === i.toString() && entry.userName === author.userName
            );
            return hourData !== undefined ? hourData.count : 0;
          }),
          backgroundColor: author.colorCode || '#cccccc'
        }))
      }
    : { labels: [], datasets: [] };

  const chartDataMinutes = data
    ? {
        labels: Array.from({ length: 60 }, (_, i) => i),
        datasets: data.postsPerMember.map((author) => ({
          label: author.name,
          data: Array.from({ length: 60 }, (_, i) => {
            const minuteData = data.postsByMinuteAndMember.find(
              (entry) => entry.minute === i.toString() && entry.userName === author.userName
            );
            return minuteData !== undefined ? minuteData.count : 0;
          }),
          backgroundColor: author.colorCode || '#cccccc'
        }))
      }
    : { labels: [], datasets: [] };

  const chartDataDayOfWeek = data
    ? {
        labels: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
        datasets: data.postsPerMember.map((author) => ({
          label: author.name,
          data: Array.from({ length: 7 }, (_, i) => {
            const dayData = data.postsByDayOfWeekAndMember.find(
              (entry) => entry.day === i.toString() && entry.userName === author.userName
            );
            return dayData !== undefined ? dayData.count : 0;
          }),
          backgroundColor: author.colorCode || '#cccccc'
        }))
      }
    : { labels: [], datasets: [] };

  return (
    <MainContentAndRightSidebar rightSidebarContent={() => <Box></Box>}>
      <Box w="full">
        {isLoading ? (
          <Center py="4">
            <Stack alignItems="center">
              <Spinner />
              <Text>{t('bluebird.members.loading')}</Text>
            </Stack>
          </Center>
        ) : isError ? (
          <Center py="4">
            <Text>
              {t('bluebird.members.error')}
              {error?.message}
            </Text>
          </Center>
        ) : data ? (
          <Stack gap="4" p="4">
            <Heading as="h1" size="2xl">
              {t('bluebird.summary.title')}
            </Heading>
            <Stack gap="4">
              <Card.Root>
                <Card.Header>
                  <Card.Title>{t('bluebird.summary.totalPosts')}</Card.Title>
                </Card.Header>
                <Card.Body>
                  <Text size="4xl" fontWeight="bold">
                    {data.totalTweets}
                  </Text>
                </Card.Body>
              </Card.Root>
              <Card.Root>
                <Card.Header>
                  <Card.Title>{t('bluebird.summary.postsByHour')}</Card.Title>
                </Card.Header>
                <Card.Body>
                  <Bar
                    data={chartData}
                    options={{
                      responsive: true,
                      plugins: {
                        legend: {
                          position: 'bottom'
                        },
                        title: {
                          display: false
                        }
                      },
                      scales: {
                        x: {
                          stacked: true
                        },
                        y: {
                          stacked: true
                        }
                      }
                    }}
                  />
                </Card.Body>
              </Card.Root>
              <Card.Root>
                <Card.Header>
                  <Card.Title>{t('bluebird.summary.postsByMinute')}</Card.Title>
                </Card.Header>
                <Card.Body>
                  <Bar
                    data={chartDataMinutes}
                    options={{
                      responsive: true,
                      plugins: {
                        legend: {
                          position: 'bottom'
                        },
                        title: {
                          display: false
                        }
                      },
                      scales: {
                        x: {
                          stacked: true
                        },
                        y: {
                          stacked: true
                        }
                      }
                    }}
                  />
                </Card.Body>
              </Card.Root>
              <Card.Root>
                <Card.Header>
                  <Card.Title>{t('bluebird.summary.postsByDayOfWeek')}</Card.Title>
                </Card.Header>
                <Card.Body>
                  <Bar
                    data={chartDataDayOfWeek}
                    options={{
                      responsive: true,
                      plugins: {
                        legend: {
                          position: 'bottom'
                        },
                        title: {
                          display: false
                        }
                      },
                      scales: {
                        x: {
                          stacked: true
                        },
                        y: {
                          stacked: true
                        }
                      }
                    }}
                  />
                </Card.Body>
              </Card.Root>
              <Card.Root>
                <Card.Header>
                  <Card.Title>{t('bluebird.summary.postsPerMember')}</Card.Title>
                </Card.Header>
                <Card.Body>
                  <Grid gap="4" gridTemplateColumns={{ base: 'repeat(2, 1fr)' }}>
                    {data.postsPerMember.map((author) => (
                      <GridItem key={author.userName}>
                        <Stack alignItems="center" borderRadius="lg" borderWidth="1px" p="2">
                          <Text fontWeight="bold">{author.name}</Text>
                          <Text>{author.tweetCount}</Text>
                        </Stack>
                      </GridItem>
                    ))}
                  </Grid>
                </Card.Body>
              </Card.Root>
            </Stack>
          </Stack>
        ) : null}
      </Box>
    </MainContentAndRightSidebar>
  );
}
