import { useQuery } from '@tanstack/react-query';
import { getCharacterByXAccount } from '../utils/character-data';
import { sortAuthorsByCustomOrder } from '~/utils/bluebirdAuthors';

export type SummaryData = {
  totalTweets: number;
  postsPerMember: {
    userName: string;
    tweetCount: number;
    colorCode?: string;
    name?: string;
  }[];
  postsByHourAndMember: {
    hour: string;
    userName: string;
    count: number;
    name?: string;
    colorCode?: string;
  }[];
  postsByMinuteAndMember: {
    minute: string;
    userName: string;
    count: number;
    name?: string;
    colorCode?: string;
  }[];
  postsByDayOfWeekAndMember: {
    day: string;
    userName: string;
    count: number;
    name?: string;
    colorCode?: string;
  }[];
};

const fetchSummaryData = async (): Promise<SummaryData> => {
  const response = await fetch('/api/bluebird/summary');
  if (!response.ok) {
    throw new Error('Network response was not ok');
  }
  const data: SummaryData = await response.json();

  const postsPerMemberWithColor = data.postsPerMember.map((member) => {
    const character = getCharacterByXAccount(member.userName);
    return {
      ...member,
      colorCode: character?.colorCode,
      name: character?.fullName
    };
  });

  const postsByHourAndMemberWithColor = data.postsByHourAndMember.map((entry) => {
    const character = getCharacterByXAccount(entry.userName);
    return {
      ...entry,
      colorCode: character?.colorCode,
      name: character?.fullName
    };
  });

  const postsByMinuteAndMemberWithColor = data.postsByMinuteAndMember.map((entry) => {
    const character = getCharacterByXAccount(entry.userName);
    return {
      ...entry,
      colorCode: character?.colorCode,
      name: character?.fullName
    };
  });

  const postsByDayOfWeekAndMemberWithColor = data.postsByDayOfWeekAndMember.map((entry) => {
    const character = getCharacterByXAccount(entry.userName);
    return {
      ...entry,
      colorCode: character?.colorCode,
      name: character?.fullName
    };
  });

  return {
    ...data,
    postsPerMember: sortAuthorsByCustomOrder(postsPerMemberWithColor),
    postsByHourAndMember: sortAuthorsByCustomOrder(postsByHourAndMemberWithColor),
    postsByMinuteAndMember: sortAuthorsByCustomOrder(postsByMinuteAndMemberWithColor),
    postsByDayOfWeekAndMember: sortAuthorsByCustomOrder(postsByDayOfWeekAndMemberWithColor)
  };
};

export function useBluebirdSummary() {
  return useQuery<SummaryData>({
    queryKey: ['bluebirdSummary'],
    queryFn: fetchSummaryData
  });
}
